def mac_bytes(mac):
    return bytes(int(part, 16) for part in mac.split(":"))


def ip_bytes(ip):
    return bytes(int(part) for part in ip.split("."))


laptop_mac, laptop_ip = "3c:22:fb:a1:07:9e", "203.0.113.20"
print(f"MAC {laptop_mac}: {len(mac_bytes(laptop_mac))} bytes, maker prefix (OUI) {laptop_mac[:8]}")
print(f"IP  {laptop_ip}: {len(ip_bytes(laptop_ip))} bytes, values {list(ip_bytes(laptop_ip))}")

# ARP: on the local network a device asks "who has this IP?" to learn the MAC to put on the frame.
lan = {"203.0.113.1": "f0:9f:c2:10:00:01", "203.0.113.7": "08:00:27:5e:aa:10"}
def arp(ip):
    return lan.get(ip, "no reply")
print("\nARP who-has 203.0.113.1 ->", arp("203.0.113.1"))
print("ARP who-has 203.0.113.99 ->", arp("203.0.113.99"))

# A packet from the laptop (on a campus network, no NAT) to a web server crosses three links.
hops = [
    ("laptop", "3c:22:fb:a1:07:9e", "campus router", "f0:9f:c2:10:00:01"),
    ("campus router", "f0:9f:c2:10:00:02", "ISP router", "00:1b:54:aa:31:07"),
    ("ISP router", "00:1b:54:aa:31:08", "web server", "52:54:00:12:34:56"),
]
dst_ip = "198.51.100.25"
print(f"\npacket {laptop_ip} -> {dst_ip}")
for sender, src_mac, receiver, dst_mac in hops:
    print(f"  {sender:13} -> {receiver:13} frame {src_mac} -> {dst_mac}  IP {laptop_ip} -> {dst_ip}")
print("\nMAC addresses: rewritten on every link (who is the next hop?)")
print("IP addresses:  the same end to end (where is the packet finally going?)")

# A tiny simulated network: servers listen on (IP, port); clients send requests and wait for replies.
listening = {}


def listen(ip, port, handler):
    listening[(ip, port)] = handler
    print(f"server listening on {ip}:{port}")


def request(client, ip, port, text):
    handler = listening.get((ip, port))
    if handler is None:
        return f"{client}: connection refused by {ip}:{port}"
    return f"{client}: sent {text!r}, got {handler(client, text)!r}"


visits = {"count": 0}


def web_server(client, text):
    visits["count"] += 1
    if text.startswith("GET /"):
        return f"200 OK page {text[4:]} (visit #{visits['count']})"
    return "400 Bad Request"


def time_server(client, text):
    return "12:00:00"                            # fixed so the output is the same every run


listen("198.51.100.25", 80, web_server)
listen("198.51.100.25", 13, time_server)

